internal static class LabelIdentifier
{
    internal static bool IsIdentifier(string value) => value.Length is > 0 and <= 32 &&
        value.All(c => c is >= '0' and <= '9' or >= 'A' and <= 'Z' or >= 'a' and <= 'z');
}

internal sealed class PreviewArguments
{
    private readonly Point3d target;
    private readonly string number;
    private readonly double height, landing, gap;

    private PreviewArguments(Point3d target, string number, double height, double landing, double gap)
    {
        this.target = target; this.number = number;
        this.height = height; this.landing = landing; this.gap = gap;
    }

    internal void Deconstruct(out Point3d target, out string number, out double height,
                              out double landing, out double gap)
    {
        target = this.target; number = this.number;
        height = this.height; landing = this.landing; gap = this.gap;
    }

    internal static Point3d ReadPoint(TypedValue[] values, ref int index)
    {
        Point3d target;
        if (index < values.Length && values[index].Value is Point3d point)
        {
            target = point;
            index++;
        }
        else if (index < values.Length && values[index].TypeCode == (int)LispDataType.ListBegin)
        {
            var coords = new List<double>();
            index++;
            while (index < values.Length && values[index].TypeCode != (int)LispDataType.ListEnd)
                coords.Add(Convert.ToDouble(values[index++].Value, CultureInfo.InvariantCulture));
            if (index >= values.Length || coords.Count is < 2 or > 3)
                throw new ArgumentException("Preview target must be a 2D/3D point.");
            index++;
            target = new Point3d(coords[0], coords[1], coords.Count == 3 ? coords[2] : 0);
        }
        else throw new ArgumentException("Preview target is missing.");
        return target;
    }

    internal static PreviewArguments Read(ResultBuffer arguments)
    {
        var values = arguments.AsArray();
        var index = 0;
        var target = ReadPoint(values, ref index);
        if (values.Length - index != 4) throw new ArgumentException("Five preview arguments required.");
        var number = (string)values[index++].Value;
        var height = Convert.ToDouble(values[index++].Value, CultureInfo.InvariantCulture);
        var landing = Convert.ToDouble(values[index++].Value, CultureInfo.InvariantCulture);
        var gap = Convert.ToDouble(values[index].Value, CultureInfo.InvariantCulture);
        if (!LabelIdentifier.IsIdentifier(number) || !LegacyNumbers.IsFinite(height) || height <= 0 ||
            !LegacyNumbers.IsFinite(landing) || landing <= 0 || !LegacyNumbers.IsFinite(gap) || gap <= 0)
            throw new ArgumentException("Invalid preview number or dimensions.");
        return new PreviewArguments(target, number, height, landing, gap);
    }
}

internal sealed class LabelJig : DrawJig, IDisposable
{
    internal static int SampleCount, FrameCount;
    private readonly DBText text;
    private readonly AcPolyline line = new();
    private readonly Point3d target;
    private readonly double height, landing, gap, width;
    private readonly string textStyleName;
    private readonly Matrix3d ucs, inverse;
    private bool valid;
    public Point3d Center { get; private set; }
    public bool EmptyResponse { get; private set; }

    public LabelJig(Database db, Point3d target, string number, double height,
                    double landing, double gap, Matrix3d ucs, ObjectId? styleOverride = null, Point3d? centerOverride = null, double widthFactor = 1)
    {
        this.target = target;
        this.height = height;
        this.landing = landing;
        this.gap = gap;
        this.ucs = ucs;
        inverse = ucs.Inverse();
        Center = centerOverride ?? target + new Vector3d(height * 6, height * 4, 0);
        text = new DBText();
        text.SetDatabaseDefaults(db);
        using var tr = db.TransactionManager.StartOpenCloseTransaction();
        var table = (TextStyleTable)tr.GetObject(db.TextStyleTableId, OpenMode.ForRead);
        if (styleOverride.HasValue) text.TextStyleId = styleOverride.Value;
        else if (table.Has(Interaction.TextStyleName)) text.TextStyleId = table[Interaction.TextStyleName];
        textStyleName = ((TextStyleTableRecord)tr.GetObject(text.TextStyleId, OpenMode.ForRead)).Name;
        text.Height = height;
        text.TextString = number;
        text.WidthFactor = widthFactor;
        text.Position = Point3d.Origin;
        width = Math.Max(height * .15, text.GeometricExtents.MaxPoint.X - text.GeometricExtents.MinPoint.X);
        text.HorizontalMode = TextHorizontalMode.TextCenter;
        text.VerticalMode = TextVerticalMode.TextVerticalMid;
        text.AlignmentPoint = Point3d.Origin;
        text.AdjustAlignment(db);
        line.SetDatabaseDefaults(db);
        for (var i = 0; i < 3; i++) line.AddVertexAt(i, Point2d.Origin, 0, 0, 0);
        Update();
    }

    protected override SamplerStatus Sampler(JigPrompts prompts)
    {
        SampleCount++;
        var options = new JigPromptPointOptions("\n移动鼠标预览整条折线，点击数字中心位置 <取消本条>: ")
        {
            UserInputControls = UserInputControls.Accept3dCoordinates |
                                UserInputControls.NullResponseAccepted |
                                UserInputControls.GovernedByOrthoMode,
            BasePoint = target.TransformBy(ucs),
            UseBasePoint = true,
            Cursor = CursorType.Crosshair
        };
        var result = prompts.AcquirePoint(options);
        if (result.Status == PromptStatus.None) EmptyResponse = true;
        if (result.Status != PromptStatus.OK) return SamplerStatus.Cancel;
        var point = result.Value.TransformBy(inverse);
        point = new Point3d(point.X, point.Y, target.Z);
        if (Center.IsEqualTo(point)) return SamplerStatus.NoChange;
        Center = point;
        Update();
        return SamplerStatus.OK;
    }

    private void Update()
    {
        var dx = target.X - Center.X;
        var dy = target.Y - Center.Y;
        var side = dx < 0 ? -1.0 : 1.0;
        var end = side * (width / 2 + gap);
        var reach = Math.Abs(dx) - (width / 2 + gap);
        var elbow = end + side * (reach > 0 ? Math.Min(landing, reach) : landing);
        line.SetPointAt(0, new Point2d(dx, dy));
        line.SetPointAt(1, new Point2d(elbow, 0));
        line.SetPointAt(2, new Point2d(end, 0));
        valid = Math.Abs(dx) > width / 2 + gap || Math.Abs(dy) > height / 2 + gap;
        line.ColorIndex = text.ColorIndex = valid ? 7 : 1;
    }

    internal string GeometrySnapshot()
    {
        var transform = ucs * Matrix3d.Displacement(Center.GetAsVector());
        var points = Enumerable.Range(0, 3).Select(i => line.GetPoint3dAt(i).TransformBy(transform))
                               .Select(p => new[] { p.X, p.Y, p.Z }).ToArray();
        return LegacyJson.Serialize(new { points, width, valid, textStyle = textStyleName,
            center = new[] { Center.TransformBy(ucs).X, Center.TransformBy(ucs).Y, Center.TransformBy(ucs).Z } });
    }

    internal Entity[] WorldCopies()
    {
        var transform = ucs * Matrix3d.Displacement(Center.GetAsVector());
        return new[] { line.GetTransformedCopy(transform), text.GetTransformedCopy(transform) };
    }

    protected override bool WorldDraw(WorldDraw draw)
    {
        FrameCount++;
        if (draw.Geometry is null) return true;
        draw.SubEntityTraits.Color = valid ? (short)7 : (short)1;
        var transform = ucs * Matrix3d.Displacement(Center.GetAsVector());
        draw.Geometry.PushModelTransform(transform);
        try { draw.Geometry.Draw(line); draw.Geometry.Draw(text); }
        finally { draw.Geometry.PopModelTransform(); }
        return true;
    }

    public void Dispose() { text.Dispose(); line.Dispose(); }
}

internal sealed class RetainedPreview : IDisposable
{
    private readonly Entity[] drawables;
    private readonly List<Entity> registered = new();
    private readonly IntegerCollection viewports = new();
    internal int DrawableCount => drawables.Length;
    internal int RegisteredCount => registered.Count;

    internal RetainedPreview(LabelJig jig)
    {
        drawables = jig.WorldCopies();
        try
        {
            var manager = TransientManager.CurrentTransientManager;
            foreach (var drawable in drawables)
                if (manager.AddTransient(drawable, TransientDrawingMode.DirectShortTerm, 128, viewports))
                    registered.Add(drawable);
        }
        catch
        {
            Dispose();
            throw;
        }
    }

    public void Dispose()
    {
        foreach (var drawable in registered)
        {
            try { TransientManager.CurrentTransientManager.EraseTransient(drawable, viewports); }
            catch (AcException) { /* The viewport may have closed already. */ }
        }
        registered.Clear();
        foreach (var drawable in drawables) drawable.Dispose();
    }
}

internal static class LegacyJson
{
    internal static string Serialize(object value) => new JavaScriptSerializer().Serialize(value);
}

internal static class LegacyNumbers
{
    internal static bool IsFinite(double value) => !double.IsNaN(value) && !double.IsInfinity(value);
}
